import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

/**
 * The grounds and fills the contrast guards measure against, read from `assets/css/main.css` (kd#194): a change of
 * `--ui-bg`, `--ui-bg-muted`, `--ui-bg-accented`, `--ui-page-bg`, `--shadow-color` or `--fill-on-canvas*` moves the
 * guards with it instead of leaving them green against the old palette. `var()` chains resolve through the `:root`
 * declarations; `--ui-color-neutral-<n>` (generated by Nuxt UI) resolves to the neutral ramp `app.config.ts` names.
 */

const root = resolve(__dirname, '../../..')
export const mainCss = readFileSync(resolve(root, 'assets/css/main.css'), 'utf8')
export const tailwindCss = readFileSync(resolve(root, 'node_modules/tailwindcss/theme.css'), 'utf8')
const appConfig = readFileSync(resolve(root, 'app.config.ts'), 'utf8')

export type Rgb = [number, number, number]
export const WHITE: Rgb = [255, 255, 255]

export function oklchToRgb(l: number, c: number, hDeg: number): Rgb {
  const h = (hDeg * Math.PI) / 180
  const a = Math.cos(h) * c
  const b = Math.sin(h) * c
  const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3
  const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3
  const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3
  const lin = [
    4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
    -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
    -0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_,
  ]
  const enc = (v: number) => {
    const x = Math.min(1, Math.max(0, v))
    return 255 * (x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055)
  }
  return [enc(lin[0]!), enc(lin[1]!), enc(lin[2]!)]
}

export function parseColor(value: string): Rgb {
  const short = value.match(/^#([0-9a-f]{3})$/i)?.[1]
  const hex = short ? [...short].map(c => c + c).join('') : value.match(/^#([0-9a-f]{6})$/i)?.[1]
  if (hex) return [0, 2, 4].map(i => parseInt(hex.slice(i, i + 2), 16)) as Rgb
  const ok = value.match(/^oklch\(\s*([\d.]+)(%?)\s+([\d.]+)\s+([\d.]+)\s*\)$/)
  if (ok) return oklchToRgb(Number(ok[1]) / (ok[2] ? 100 : 1), Number(ok[3]), Number(ok[4]))
  throw new Error(`unsupported colour: ${value}`)
}

/** `--color-<ramp>-<step>`: the project's own palettes from main.css, the others from Tailwind's theme. */
export function rampStep(ramp: string, step: string): Rgb {
  const source = ramp.startsWith('custom-') ? mainCss : tailwindCss
  const value = source.match(new RegExp(`--color-${ramp}-${step}:\\s*([^;]+);`))?.[1]?.trim()
  if (!value) throw new Error(`ramp ${ramp}-${step} not found`)
  return parseColor(value)
}

/** The raw value of a custom property declared in main.css (the first declaration wins). */
function declaration(name: string): string {
  const value = mainCss.match(new RegExp(`${name.replace(/[-]/g, '\\-')}:\\s*([^;]+);`))?.[1]?.trim()
  if (!value) throw new Error(`${name} not declared in assets/css/main.css`)
  return value
}

/** A `--color-*` theme variable: the project's `main.css` first, Tailwind's default theme (`--color-white`) second. */
function themeValue(name: string): string {
  const pattern = new RegExp(`${name}:\\s*([^;]+);`)
  const value = (mainCss.match(pattern) ?? tailwindCss.match(pattern))?.[1]?.trim()
  if (!value) throw new Error(`${name} not found in main.css or Tailwind's theme`)
  return value
}

/** A colour custom property as an RGB, following `var(--x)` chains and the generated `--ui-color-neutral-<n>`. */
export function cssColor(name: string): Rgb {
  const neutral = appConfig.match(/neutral:\s*'([^']+)'/)?.[1]
  const generated = name.match(/^--ui-color-neutral-(\d+)$/)
  if (generated) {
    if (!neutral) throw new Error('no `neutral` colour in app.config.ts')
    return rampStep(neutral, generated[1]!)
  }
  const value = declaration(name)
  const ref = value.match(/^var\((--[\w-]+)\)$/)?.[1]
  if (ref) return ref.startsWith('--color-') ? parseColor(themeValue(ref)) : cssColor(ref)
  return parseColor(value)
}

/** The white sheet (`--ui-bg`), the fill inside a sheet (`--ui-bg-muted`) and the paper canvas (`--ui-page-bg`). */
export const SHEET: Rgb = cssColor('--ui-bg')
export const SHEET_ELEVATED: Rgb = cssColor('--ui-bg-elevated')
export const SHEET_FILL: Rgb = cssColor('--ui-bg-muted')
export const SHEET_FILL_DEEP: Rgb = cssColor('--ui-bg-accented')
export const PAPER: Rgb = cssColor('--ui-page-bg')

const hex = (c: Rgb) => `#${c.map(v => Math.round(v).toString(16).padStart(2, '0')).join('')}`
/** The grounds a component sits on, labelled with the token and the value it resolved to. */
export const GROUNDS: Array<[string, Rgb]> = [
  [`sheet --ui-bg ${hex(SHEET)}`, SHEET],
  [`sheet fill --ui-bg-muted ${hex(SHEET_FILL)}`, SHEET_FILL],
  [`paper --ui-page-bg ${hex(PAPER)}`, PAPER],
]

/** `--shadow-color`, an rgb triplet (`70 48 20`). */
export const SHADOW_COLOR: Rgb = declaration('--shadow-color').split(/\s+/).map(Number) as Rgb

/** The alpha of a `--fill-on-canvas*` token: `rgb(var(--shadow-color) / 0.07)`. */
function fillAlpha(name: string): number {
  const alpha = Number(declaration(name).match(/\/\s*([\d.]+)\s*\)$/)?.[1])
  if (Number.isNaN(alpha)) throw new Error(`${name}: no alpha found`)
  return alpha
}
/** The fills that sit on the canvas, keyed by the Tailwind class suffix a button compound uses. */
export const FILLS_ON_CANVAS: Record<string, number> = {
  '(--fill-on-canvas)': fillAlpha('--fill-on-canvas'),
  '(--fill-on-canvas-hover)': fillAlpha('--fill-on-canvas-hover'),
}
